package com.interviewiq.config;
import com.interviewiq.domain.Question;import com.interviewiq.domain.AppUser;import com.interviewiq.repository.QuestionRepository;import com.interviewiq.repository.UserRepository;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.security.crypto.password.PasswordEncoder;import java.util.List;
@Configuration public class SeedData {
 @Bean CommandLineRunner seed(QuestionRepository repo,UserRepository users,PasswordEncoder encoder,@Value("${app.admin.email:}") String adminEmail,@Value("${app.admin.password:}") String adminPassword){return args->{if(repo.count()==0)repo.saveAll(List.of(
  new Question("Which OOP principle allows one interface to represent different underlying forms?","MCQ","OOP","MEDIUM",List.of("Encapsulation","Inheritance","Polymorphism","Abstraction"),"Polymorphism","Polymorphism lets implementations respond differently through a shared contract.",""),
  new Question("Which collection preserves insertion order and allows duplicates?","MCQ","Collections","EASY",List.of("HashSet","ArrayList","TreeSet","Map"),"ArrayList","ArrayList is an ordered list that permits duplicate elements.",""),
  new Question("In Java, a class can extend more than one class.","TRUE_FALSE","Core Java","EASY",List.of("True","False"),"False","Java classes use single inheritance; multiple interfaces may be implemented.",""),
  new Question("What is dependency injection in Spring, and why is it useful?","TECHNICAL","Spring Boot","MEDIUM",List.of(),null,"Describe how the container supplies dependencies to reduce coupling.","IoC, Dependency Injection, Spring Container, Loose Coupling"),
  new Question("How would you explain a database index and its trade-offs?","TECHNICAL","SQL","MEDIUM",List.of(),null,"Explain faster reads alongside storage and write costs.","index, query, read, write, storage"),
  new Question("Tell me about a project challenge and how you handled it.","BEHAVIORAL","Communication","MEDIUM",List.of(),null,"Use a clear situation, action, and result with specific impact.","situation, action, result, challenge"),
  new Question("Which keyword prevents a Java method from being overridden?","MCQ","Core Java","EASY",List.of("static","final","volatile","native"),"final","A final method cannot be overridden by subclasses.",""),
  new Question("Which OOP concept hides internal state and exposes controlled operations?","MCQ","OOP","EASY",List.of("Encapsulation","Inheritance","Overloading","Casting"),"Encapsulation","Encapsulation protects state behind a well-defined API.",""),
  new Question("What is one practical benefit of Spring Boot auto-configuration?","MCQ","Spring Boot","MEDIUM",List.of("It removes all configuration permanently","It configures common beans based on dependencies and settings","It replaces the Java compiler","It makes every endpoint public"),"It configures common beans based on dependencies and settings","Auto-configuration provides sensible defaults based on the classpath and application configuration.",""),
  new Question("Which SQL clause filters grouped aggregate results?","MCQ","SQL","MEDIUM",List.of("WHERE","HAVING","ORDER BY","LIMIT"),"HAVING","HAVING filters groups after aggregation.",""),
  new Question("What is the difference between an interface and an abstract class in Java?","TECHNICAL","OOP","MEDIUM",List.of(),null,"Compare contracts, state, constructors, and inheritance flexibility.","contract, implementation, state, constructor"),
  new Question("How would you design a REST endpoint for creating a resource?","TECHNICAL","Spring Boot","MEDIUM",List.of(),null,"Discuss HTTP method, request validation, status codes, and resource location.","POST, validation, status code, resource"),
  new Question("When would you use a SQL JOIN, and how do common join types differ?","TECHNICAL","SQL","MEDIUM",List.of(),null,"Explain combining related rows and inner versus outer joins.","join, inner, left, related rows"),
  new Question("Tell me about a time you worked with someone to solve a difficult problem.","BEHAVIORAL","Communication","MEDIUM",List.of(),null,"Use a clear situation, action, and result with specific impact.","situation, action, result, collaboration")
 ));if(!adminEmail.isBlank()&&!adminPassword.isBlank()&&adminPassword.length()>=8){AppUser admin=users.findByEmailIgnoreCase(adminEmail).orElseGet(()->new AppUser("Interview-IQ Admin",adminEmail.toLowerCase(),encoder.encode(adminPassword)));admin.setRole("ADMIN");users.save(admin);}};}
}
